FUNCTION handleDeleteDevice(request, device_id):
    // REQ-2-026; Preconditions: persistence available. REQUIRE owner/admin or RETURN 401/403.
    IF device_id <= 0 OR absent THEN RETURN 404. BEGIN TRANSACTION; DELETE device only; COMMIT; RETURN 204.
    // REQ-2-008. Repeat returns 404; rollback retains the device and unchanged hub/room relations and revisions.

FUNCTION handleDeleteHub(request, hub_id):
    // REQ-2-016; Preconditions: persistence available. REQUIRE owner/admin or RETURN 401/403.
    IF hub_id <= 0 OR absent THEN RETURN 404. BEGIN TRANSACTION.
    IF any room or device belongs to hub THEN ROLLBACK; RETURN 409 under REQ-2-008. END IF DELETE hub; COMMIT; RETURN 204.
    // Repeat returns 404; all error paths preserve hub, child relations, and revisions.

FUNCTION handleDeleteRoom(request, room_id):
    // REQ-2-021; Preconditions: persistence available. REQUIRE owner/admin or RETURN 401/403.
    IF room_id <= 0 OR absent THEN RETURN 404. BEGIN TRANSACTION.
    IF device refers to room THEN ROLLBACK; RETURN 409 under REQ-2-008. END IF DELETE room; COMMIT; RETURN 204.
    // Repeat returns 404; errors leave room, hub, devices, and revisions unchanged.

FUNCTION handleListDevices(request):
    // REQ-2-022; Preconditions: persistence available. REQUIRE authenticated caller or RETURN 401.
    VALIDATE enum, boolean, pagination, and supplied parent ids or RETURN 422/404. IF user caller does not own selected parent hub/room THEN RETURN 403.
    READ owner-visible devices matching exact filters, sort id, page, RETURN 200.
    // Transaction: none; postcondition: device topology and revisions unchanged.

FUNCTION handleGetHealth(request):
    // REQ-2-011; Preconditions: none. Authorization: public. Transaction: none.
    IF local persistence probe fails THEN RETURN 503. END IF
    RETURN 200 with status = ok.
    // Postcondition: hubs, rooms, devices, and revisions are unchanged.

FUNCTION handleListHubs(request):
    // REQ-2-012; Preconditions: persistence available. REQUIRE authenticated caller or RETURN 401.
    VALIDATE timezone and pagination or RETURN 422. IF owner_id <= 0 OR owner absent THEN RETURN 404.
    IF caller is user and owner_id is another user THEN RETURN 403. READ visible hubs by id page; RETURN 200.
    // Transaction: none; postcondition: no persistent state, including revisions, changes.

FUNCTION handleGetHub(request, hub_id):
    // REQ-2-014; Preconditions: persistence available. REQUIRE authenticated caller or RETURN 401.
    IF hub_id <= 0 OR hub absent THEN RETURN 404. IF user caller is not hub owner THEN RETURN 403.
    READ hub; RETURN 200 with ETag for REQ-2-005.
    // Transaction: none; postcondition: all state and revisions are unchanged.

FUNCTION handleGetHubTopology(request, hub_id):
    // REQ-2-027; Preconditions: persistence available. REQUIRE authenticated caller or RETURN 401.
    IF hub_id <= 0 OR absent THEN RETURN 404. IF user caller is not hub owner THEN RETURN 403.
    READ hub, rooms, and devices using REQ-2-010 ordering; RETURN 200.
    // Transaction: none. Postcondition: the entire topology and all revisions remain unchanged.

FUNCTION handleListRooms(request):
    // REQ-2-017; Preconditions: persistence available. REQUIRE authenticated caller or RETURN 401.
    VALIDATE floor and pagination or RETURN 422. IF supplied hub_id <= 0 OR absent THEN RETURN 404.
    IF user caller does not own selected hub THEN RETURN 403. READ visible rooms by id page; RETURN 200.
    // Transaction: none; postcondition: topology and revisions unchanged.

FUNCTION handlePatchDevice(request, device_id):
    // REQ-2-025; Preconditions: JSON, exact If-Match, existing device, persistence available. REQUIRE owner/admin or RETURN 401/403.
    REQUIRE JSON or RETURN 415; parse or RETURN 400; VALIDATE non-empty patch, field syntax, and ETag format or RETURN 422; invalid id/absence RETURN 404.
    BEGIN TRANSACTION; lock device, hub, and proposed room. IF If-Match stale THEN ROLLBACK; RETURN 409 current ETag. IF room mismatches hub, capacity fails, or label duplicate THEN ROLLBACK; RETURN 409. END IF
    APPLY only supplied fields; increment device revision only; COMMIT; RETURN 200 new ETag.
    // Null room_id unassigns; other nulls are 422. Errors rollback all relations and every revision.

FUNCTION handlePatchHub(request, hub_id):
    // REQ-2-015; Preconditions: JSON, exact If-Match, positive existing hub, persistence available. REQUIRE owner/admin or RETURN 401/403.
    REQUIRE JSON or RETURN 415; parse or RETURN 400; IF hub_id invalid/absent RETURN 404; VALIDATE non-empty non-null fields and ETag syntax or RETURN 422.
    BEGIN TRANSACTION; lock hub. IF If-Match != current ETag THEN ROLLBACK; RETURN 409 with current ETag under REQ-2-007. END IF
    APPLY supplied fields; revision = revision + 1; COMMIT; RETURN 200 with new ETag.
    // Not idempotent. Any error rolls back: hub, rooms, devices, and every revision remain unchanged.

FUNCTION handlePatchRoom(request, room_id):
    // REQ-2-020; Preconditions: JSON, If-Match, existing room, persistence available. REQUIRE owner/admin or RETURN 401/403.
    REQUIRE JSON or RETURN 415; parse or RETURN 400; validate patch and ETag format or RETURN 422; invalid id/absence RETURN 404.
    BEGIN TRANSACTION; lock room. IF stale ETag OR resulting case-insensitive duplicate name THEN ROLLBACK; RETURN 409 with current ETag when stale. END IF
    UPDATE supplied fields; increment room revision only; COMMIT; RETURN 200 new ETag.
    // Not idempotent. On error no topology, device assignment, or revision changes occur.

FUNCTION handleCreateDevice(request):
    // REQ-2-023; Preconditions: JSON and persistence available. REQUIRE authenticated caller or RETURN 401; REQUIRE JSON or RETURN 415; parse or RETURN 400.
    VALIDATE fields or RETURN 422; verify hub and optional room positive/existing/same hub and caller ownership or RETURN 404/403.
    BEGIN TRANSACTION; lock hub and room. IF capacity exceeded or label/address duplicate THEN ROLLBACK; RETURN 409. END IF CREATE device revision 1; COMMIT; RETURN 201 Location and ETag.
    // Non-idempotent; rollback leaves all topology and revisions unchanged.

FUNCTION handleCreateHub(request):
    // REQ-2-013; Preconditions: JSON and persistence available. REQUIRE authenticated caller or RETURN 401; REQUIRE JSON or RETURN 415; parse or RETURN 400.
    RESOLVE owner: user caller, or positive existing admin-supplied owner; reject forbidden owner with 403 and absent with 404. VALIDATE REQ-2-001 or RETURN 422.
    BEGIN TRANSACTION; IF serial exists THEN ROLLBACK; RETURN 409. END IF CREATE hub revision 1; COMMIT; RETURN 201 Location and ETag.
    // Non-idempotent. Any error rolls back with no hub, room, or device relation changed.

FUNCTION handleCreateRoom(request):
    // REQ-2-018; Preconditions: JSON and persistence available. REQUIRE authenticated caller or RETURN 401; REQUIRE JSON or RETURN 415; parse or RETURN 400.
    VALIDATE hub id/name/floor under REQ-2-002 or RETURN 422. IF hub invalid/absent RETURN 404; IF user does not own hub RETURN 403.
    BEGIN TRANSACTION; IF case-insensitive name exists in hub THEN ROLLBACK RETURN 409; CREATE room revision 1; COMMIT RETURN 201 Location and ETag.
    // Non-idempotent. Rollback preserves hub, rooms, devices, and revisions.
